css:
#loader-21 {
  display: inline-grid;
  width: 80px;
  aspect-ratio: 1;
}
#loader-21:before,
#loader-21:after {
  content: '';
  grid-area: 1/1;
  border-radius: 50%;
}
#loader-21:before {
  margin: 25%;
  background: repeating-conic-gradient(#C02942 0 60deg,#0B486B 0 120deg);
  transform: rotate(0turn) translate(50%) rotate(0turn);
  animation: l1 3s linear infinite;
}
#loader-21:after {
  padding: 10%;
  margin: -10%;
  background: repeating-conic-gradient(from -15deg,#C02942 0 30deg,#0B486B 0 60deg);
  mask: conic-gradient(#000 0 0) content-box exclude,conic-gradient(#000 0 0);
}
@keyframes l1 {
  to{transform: rotate(1turn) translate(50%) rotate(-2turn)}
}
